// Benchmark result structure
struct BenchmarkResult {
    std::string name;
    double duration_ms;
    double memory_usage_mb;
    uint64_t operations_performed;
    double operations_per_second;
    std::chrono::system_clock::time_point timestamp;
    std::string metadata;
};

// Benchmark suite for different components
class BenchmarkSuite {
private:
    std::vector<BenchmarkResult> results_;
    bool enabled_ = false;
    
public:
    explicit BenchmarkSuite(bool enabled = false) : enabled_(enabled) {}
    
    void record(const std::string& name, double duration_ms,
                double memory_usage_mb = 0.0, uint64_t operations = 0) {
        if (!enabled_) return;
        
        BenchmarkResult result;
        result.name = name;
        result.duration_ms = duration_ms;
        result.memory_usage_mb = memory_usage_mb;
        result.operations_performed = operations;
        result.operations_per_second = operations > 0 ? operations / (duration_ms / 1000.0) : 0.0;
        result.timestamp = std::chrono::system_clock::now();
        result.metadata = "benchmark";
        
        results_.push_back(result);
    }
    
    const std::vector<BenchmarkResult>& get_results() const { return results_; }
    
    void save_to_file(const std::string& filename) const {
        if (!enabled_) return;
        
        std::ofstream file(filename);
        if (!file.is_open()) return;
        
        file << "# NLM Benchmark Results\n";
        file << "# Generated at " << std::chrono::system_clock::now() << "\n\n";
        
        file << "BenchmarkName,Duration(ms),MemoryUsage(MB),Operations,OpsPerSecond,Timestamp\n";
        
        for (const auto& result : results_) {
            file << result.name << ","
                 << std::fixed << std::setprecision(6) << result.duration_ms << ","
                 << std::fixed << std::setprecision(2) << result.memory_usage_mb << ","
                 << result.operations_performed << ","
                 << std::fixed << std::setprecision(2) << result.operations_per_second << ","
                 << std::chrono::system_clock::to_time_t(result.timestamp) << "\n";
        }
        
        file.close();
    }
    
    double get_average_time(const std::string& name) const {
        std::vector<double> times;
        for (const auto& result : results_) {
            if (result.name == name) {
                times.push_back(result.duration_ms);
            }
        }
        
        if (times.empty()) return 0.0;
        
        return std::accumulate(times.begin(), times.end(), 0.0) / times.size();
    }
    
    double get_min_time(const std::string& name) const {
        std::vector<double> times;
        for (const auto& result : results_) {
            if (result.name == name) {
                times.push_back(result.duration_ms);
            }
        }
        
        if (times.empty()) return 0.0;
        
        return *std::min_element(times.begin(), times.end());
    }
    
    double get_max_time(const std::string& name) const {
        std::vector<double> times;
        for (const auto& result : results_) {
            if (result.name == name) {
                times.push_back(result.duration_ms);
            }
        }
        
        if (times.empty()) return 0.0;
        
        return *std::max_element(times.begin(), times.end());
    }
    
    void clear() { results_.clear(); }
};

// Global benchmark instance
inline BenchmarkSuite& get_benchmark_suite() {
    static BenchmarkSuite suite(NLM_ENABLE_BENCHMARKS);
    return suite;
}

// Benchmark macros for timing code sections
#define NLM_BENCHMARK(name) \
    auto _##name##_start = std::chrono::high_resolution_clock::now(); \
    \
    auto _##name##_stop = std::chrono::high_resolution_clock::now(); \
    auto _##name##_duration = std::chrono::duration_cast<std::chrono::milliseconds>(_##name##_stop - _##name##_start).count(); \
    nlm::benchmarks::get_benchmark_suite().record(#name, _##name##_duration);

#define NLM_BENCHMARK_WITH_OPS(name, ops) \
    auto _##name##_start = std::chrono::high_resolution_clock::now(); \
    \
    auto _##name##_stop = std::chrono::high_resolution_clock::now(); \
    auto _##name##_duration = std::chrono::duration_cast<std::chrono::milliseconds>(_##name##_stop - _##name##_start).count(); \
    nlm::benchmarks::get_benchmark_suite().record(#name, _##name##_duration, 0, ops);

